const V=window.SugarCube.State.variables;
const out={};
out.phone_active_flag = (V.flags||{}).phone_active || false;
out.setup_phone_enabled = window.SugarCube.setup.phone_enabled;
out.setup_purchase_flag = window.SugarCube.setup.phone_purchase_flag;
// is the phone button in the DOM right now?
out.phoneBtnPresent = !!([...document.querySelectorAll('a,button,div')].find(e=>/📱\s*Phone/.test(e.textContent||'')));
// count phone conversations in setup data
out.convCount = (window.SugarCube.setup.phone_data && window.SugarCube.setup.phone_data.conversations||[]).length;
out.dailyTopicCount = (window.SugarCube.setup.phone_data && window.SugarCube.setup.phone_data.daily_topics||[]).length;
return JSON.stringify(out,null,1);

const V=window.SugarCube.State.variables;
V.flags=V.flags||{};
V.flags.phone_active=true;
V.flags.hired_at_diner=true;
V.flags.hank_opened_up=true;
V.flags.hank_first_contact=true;
V.flags.cole_noticed=true;
V.player.core_traits.corruption=50;   // >=45 lewd unlocked, <85 nude locked
// re-render to refresh sidebar (and run delivery scan)
window.SugarCube.Engine.play(window.SugarCube.State.passage);
return 'set';

const out={};
out.phoneBtnPresent = !!([...document.querySelectorAll('a,button,div')].find(e=>/📱\s*Phone/.test(e.textContent||'')));
// run the delivery scan and inspect triggered conversations
if(typeof window.SugarCube.setup.checkPhoneConversations==='function'){ try{window.SugarCube.setup.checkPhoneConversations();}catch(e){out.scanErr=e.message;} }
const ps=(window.SugarCube.State.variables.game_state||{}).phone||{};
out.triggered = Object.keys(ps.triggered_conversations||{});
// which threads does getPhoneThreads see?
if(typeof window.SugarCube.setup.getPhoneThreads==='function'){
  const th=window.SugarCube.setup.getPhoneThreads('messages')||[];
  out.threads = th.map(t=>({npc:t.npcName, convs:(t.conversations||[]).map(c=>c.id), unread:t.unreadCount}));
}
return JSON.stringify(out,null,1);

// click the Hank thread tile
const tiles=[...document.querySelectorAll('.phone-thread-item,[class*=thread]')].map(e=>({t:(e.textContent||'').trim().slice(0,30),cls:e.className}));
// open hank thread directly via API
try{ window.SugarCube.setup.openChatThread('messages','npc_hank'); }catch(e){ return 'threadErr:'+e.message; }
return JSON.stringify({tiles:tiles.slice(0,8)});

// enumerate the action buttons + any locked indicators in the open thread
const btns=[...document.querySelectorAll('.phone-daily-btn,[class*=daily],[class*=topic],button,a')].map(e=>{const t=(e.textContent||'').trim();const cls=e.className||'';const dis=e.disabled||/lock|disabled/i.test(cls);return {t:t.slice(0,40),cls:cls.slice(0,40),dis};}).filter(e=>/selfie|lewd|nude|send|say|still there/i.test(e.t));
return JSON.stringify(btns.slice(0,20),null,1);

const V=window.SugarCube.State.variables;
const before=(V.npcs.npc_hank.core_traits||{}).arousal;
// reply 'Keep it warm for me.' = choice index 1 (hank arousal +1)
try{ window.SugarCube.setup.sendPhoneReply('hank_jacket',1,1); }catch(e){ return 'replyErr:'+e.message; }
const after=(V.npcs.npc_hank.core_traits||{}).arousal;
return JSON.stringify({hank_arousal_before:before, hank_arousal_after:after});

// re-open hank thread to render the daily-topic / photo-action area
try{ window.SugarCube.setup.openChatThread('messages','npc_hank'); }catch(e){ return 'e:'+e.message; }
return 'reopened';

const V=window.SugarCube.State.variables;
const out={npcKeys:Object.keys(V.npcs||{}).slice(0,8)};
// find hank by slug/name
for(const k of Object.keys(V.npcs||{})){const n=V.npcs[k]; if(n && (n.slug==='npc_hank'||n.id==='npc_hank'||/hank/i.test(n.name||''))){ out.hank={key:k, arousal:(n.core_traits||{}).arousal, relation:(n.core_traits||{}).relation}; }}
// replies recorded?
const ps=(V.game_state||{}).phone||{};
out.replies=ps.replies||{};
return JSON.stringify(out,null,1);

const V=window.SugarCube.State.variables;
const HK='ac2de4f4-9e94-4f9b-be13-2d4e87e883e5';
const before=(V.npcs[HK].core_traits||{}).arousal;
try{ window.SugarCube.setup.sendPhoneReply('hank_jacket',1,1); }catch(e){ return 'replyErr:'+e.message; }
const after=(V.npcs[HK].core_traits||{}).arousal;
const ps=(V.game_state||{}).phone||{};
return JSON.stringify({hank_arousal_before:before, hank_arousal_after:after, replies:ps.replies});

const V=window.SugarCube.State.variables;
V.player.core_traits.corruption=20;   // below 45 — lewd should vanish
try{ window.SugarCube.setup.openChatThread('messages','npc_hank'); }catch(e){}
return 'set20';

const V=window.SugarCube.State.variables;
// backdate hired_at_diner so days_since >=4
V.flags_meta=V.flags_meta||{};
const cur=(V.game_state&&V.game_state.time_state)?V.game_state.time_state.day:1;
V.flags_meta.hired_at_diner={set_day: cur-5};
V.flags.rent_evicted=true;
try{ window.SugarCube.setup.checkPhoneConversations(); }catch(e){return 'scanErr:'+e.message;}
const ps=(V.game_state||{}).phone||{};
return JSON.stringify({triggered:Object.keys(ps.triggered_conversations||{})});
